// Practice projects. Every number below is read from projects/data/answers.json, which tools/make_data.py computes
// from the generated files, so the pages cannot drift from the downloads. The data is synthetic.

const esc = (t) => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const money = (s) => { const [i, d] = String(s).split("."); return i.replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (d ? "." + d : ""); };
const num = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const pre = (s) => `<pre><code>${esc(s)}</code></pre>`;
const table = (head, rows) => `<table>
  <tr>${head.map((h) => `<th>${esc(h)}</th>`).join("")}</tr>
  ${rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("\n  ")}
</table>`;

module.exports = function projects(A) {
  const p1 = A.project1, p2 = A.project2, p3 = A.project3;
  const SYN = `<div class="callout"><b>Synthetic data</b> Every file here was generated by a seeded script. It describes no real company, person or sale, and the products and customer IDs are made up.</div>`;
  const VERIFY = (what) => `<div class="callout"><b>How the answers were checked</b> ${what} I could not open Excel, Google Sheets or Power BI to run these steps, so small differences in rounding or display are possible. If your numbers differ by more than a cent, recheck your steps before the data.</div>`;

  /* ---------- Project 1: Excel or Google Sheets ---------- */
  const proj1 = {
    slug: "sales-cleanup-excel-sheets",
    title: "Project 1: Clean and Analyse a Messy Sales File",
    tool: "Excel or Google Sheets", level: "Beginner to intermediate", time: "About 1 to 2 hours (estimate)",
    files: ["sales_raw.csv"],
    guide: ["excel-study-guide", "Excel study guide"],
    excerpt: "Download a deliberately messy synthetic sales CSV, clean it, then calculate totals, a regional breakdown, a monthly pivot and a chart. Includes an answer key.",
    intro: `You have been handed a raw export of one year of orders (2025) from a small fictional retailer. It has real-world problems: duplicate rows, inconsistent spelling in the Region column, and placeholder rows with no quantity. Clean it, then answer questions about it. Work in Excel or Google Sheets. For formulas and pivots, see the <a href="../../guides/excel-study-guide/">Excel study guide</a> or the <a href="../../guides/google-sheets-study-guide/">Google Sheets study guide</a>.`,
    sections: [
      { h: "The data", body: `${SYN}
        <p>Download <a href="../data/sales_raw.csv" download>sales_raw.csv</a> (${num(p1.raw_rows)} data rows). Columns: OrderID, OrderDate, Region, Product, Category, Quantity, UnitPrice, Discount. Dates are written as YYYY-MM-DD. Discount is a fraction (0.10 means 10%).</p>
        <p><b>Revenue</b> for an order is <code>Quantity × UnitPrice × (1 − Discount)</code>.</p>` },
      { h: "Tasks", body: `
        <ol>
          <li><b>Open and inspect.</b> Import or open the CSV. How many data rows are there? Check that OrderDate is recognised as a date and Quantity as a number. Scan the Region column for oddities.</li>
          <li><b>Fix the Region column.</b> Remove stray spaces and make the capitalisation consistent, so there are exactly four regions: North, South, East, West. (Hint: <code>TRIM</code> and <code>PROPER</code>.)</li>
          <li><b>Remove exact duplicate rows.</b> A repeated row is the same order exported twice.</li>
          <li><b>Remove placeholder rows.</b> Delete rows where Quantity is "N/A". They are not real orders.</li>
          <li><b>Add a Revenue column</b> using the formula above, and format it as currency with 2 decimals.</li>
          <li><b>Answer:</b> total revenue; revenue by region (try <code>SUMIFS</code>); revenue by category; the product with the highest revenue; revenue for each month (a pivot table works well); the number of orders that had a discount.</li>
          <li><b>Chart it.</b> Make a column chart of revenue by month with a clear title and axis labels.</li>
        </ol>` },
      { h: "Answer key", body: `
        <details class="faq"><summary>Show the expected results</summary>
          ${table(["Check", "Expected"], [
            ["Data rows in the raw file", num(p1.raw_rows)],
            ["Duplicate rows removed", String(p1.duplicate_rows)],
            ["Placeholder (N/A quantity) rows removed", String(p1.junk_rows)],
            ["Region cells with spacing or capitalisation problems", String(p1.messy_region_cells)],
            ["Rows after cleaning", num(p1.clean_rows)],
            ["Total revenue", money(p1.total_revenue)],
            ["Orders with a discount above 0", num(p1.discounted_orders)],
            ["Highest-revenue product", `${p1.top_product.name} (${money(p1.top_product.revenue)})`],
          ])}
          <p><b>Revenue by region</b></p>
          ${table(["Region", "Revenue"], Object.entries(p1.revenue_by_region).map(([k, v]) => [k, money(v)]))}
          <p><b>Revenue by category</b></p>
          ${table(["Category", "Revenue"], Object.entries(p1.revenue_by_category).map(([k, v]) => [k, money(v)]))}
          <p><b>Revenue by month, 2025</b></p>
          ${table(["Month", "Revenue"], Object.entries(p1.revenue_by_month).map(([k, v]) => [k, money(v)]))}
          ${VERIFY("These figures were computed by script with exact decimal arithmetic from the same rows you download, and cross-checked against the SQL project's 2025 results.")}
        </details>` },
      { h: "Stretch ideas", body: `
        <ul>
          <li>Use <code>XLOOKUP</code> or <code>VLOOKUP</code> to add each product's category from a separate small product table you build yourself.</li>
          <li>Add a data validation drop-down for Region so bad values cannot be typed in again.</li>
          <li>Write two sentences for a manager: what the data shows, and one thing you would check next.</li>
        </ul>` },
    ],
  };

  /* ---------- Project 2: SQL ---------- */
  const qBlocks = p2.queries.map((q, i) => {
    const head = q.columns;
    const shown = q.rows.slice(0, 12);
    return `<h3>Task ${i + 1}: ${esc(q.title)}</h3>
        <p>${esc(q.task)}</p>
        <details class="faq"><summary>Show a solution and the expected result</summary>
          ${pre(q.sql)}
          ${table(head, shown)}
          <p class="muted">${q.row_count} row${q.row_count === 1 ? "" : "s"}${q.row_count > shown.length ? ` (first ${shown.length} shown)` : ""}.</p>
        </details>`;
  }).join("\n        ");
  const proj2 = {
    slug: "shop-sql-queries",
    title: "Project 2: Answer Business Questions with SQL",
    tool: "SQL (SQLite)", level: "Intermediate", time: "About 1 to 2 hours (estimate)",
    files: ["shop.sql"],
    guide: ["sql-study-guide", "SQL study guide"],
    excerpt: "Load a small synthetic shop database into SQLite and write eight queries: joins, aggregation, a LEFT JOIN anti-join, HAVING and a window function. Includes tested solutions.",
    intro: `A fictional shop keeps customers, products and orders (2024 and 2025) in three tables. Load the data and answer eight questions with SQL. For joins, grouping and window functions, see the <a href="../../guides/sql-study-guide/">SQL study guide</a>.`,
    sections: [
      { h: "Set up", body: `${SYN}
        <p>Download <a href="../data/shop.sql" download>shop.sql</a>. It creates three tables and inserts the rows (${num(p2.tables.customers)} customers, ${num(p2.tables.products)} products, ${num(p2.tables.orders)} orders). With the SQLite command-line tool:</p>
        ${pre("sqlite3 shop.db < shop.sql")}
        <p>Or with Python, which includes SQLite:</p>
        ${pre("python3 -c \"import sqlite3; c = sqlite3.connect('shop.db'); c.executescript(open('shop.sql').read())\"")}
        ${table(["Table", "Columns"], [
          ["customers", "CustomerID, Region, Segment"],
          ["products", "ProductID, Product, Category, UnitPrice"],
          ["orders", "OrderID, OrderDate (YYYY-MM-DD text), CustomerID, ProductID, Quantity, Discount"],
        ])}
        <p><b>Revenue</b> for an order is <code>Quantity × UnitPrice × (1 − Discount)</code>. The solutions are written for SQLite; date functions and some syntax differ in other databases.</p>` },
      { h: "Tasks", body: `
        <p>Try each query yourself before you open the solution. Your result should match the expected rows, including the order.</p>
        ${qBlocks}` },
      { h: "How the answers were checked", body: `
        <p>Every solution above was executed against the downloadable <code>shop.sql</code> in SQLite ${esc(A.sqlite_version || "")} and the expected results come from those runs. A separate check recomputed the totals with exact decimal arithmetic. Other database systems may format or round results slightly differently.</p>` },
      { h: "Stretch ideas", body: `
        <ul>
          <li>Find each customer's most recent order date.</li>
          <li>Rank products by revenue within each category using <code>RANK() OVER (PARTITION BY ...)</code>.</li>
          <li>Create a view for revenue per order and query the view instead.</li>
        </ul>` },
    ],
  };

  /* ---------- Project 3: Power BI ---------- */
  const proj3 = {
    slug: "power-bi-sales-model",
    title: "Project 3: Build a Star Schema and DAX Measures in Power BI",
    tool: "Power BI Desktop", level: "Intermediate", time: "About 2 hours (estimate)",
    files: ["orders.csv", "products.csv", "customers.csv", "dim_date.csv"],
    guide: ["power-bi-study-guide", "Power BI study guide"],
    excerpt: "Load four synthetic CSV tables into Power BI Desktop, model them as a star schema with a date table, write three DAX measures and build a one-page report. Includes expected values.",
    intro: `Build a small sales model from four tables, write measures for sales and year-over-year change, and design one report page. It practises what the <a href="../../guides/power-bi-study-guide/">Power BI study guide</a> explains: star schemas, relationships, date tables and <code>CALCULATE</code>.`,
    sections: [
      { h: "The data", body: `${SYN}
        <table>
          <tr><th>File</th><th>Role</th><th>Rows</th></tr>
          <tr><td><a href="../data/orders.csv" download>orders.csv</a></td><td>Fact table (one row per order): OrderID, OrderDate, CustomerID, ProductID, Quantity, Discount</td><td>${num(p3.fact_rows)}</td></tr>
          <tr><td><a href="../data/products.csv" download>products.csv</a></td><td>Dimension: ProductID, Product, Category, UnitPrice</td><td>${num(p3.product_rows)}</td></tr>
          <tr><td><a href="../data/customers.csv" download>customers.csv</a></td><td>Dimension: CustomerID, Region, Segment</td><td>${num(p3.customer_rows)}</td></tr>
          <tr><td><a href="../data/dim_date.csv" download>dim_date.csv</a></td><td>Date table: one row per day from 2024-01-01 to 2025-12-31</td><td>${num(p3.date_rows)}</td></tr>
        </table>
        <p>There is no revenue column on purpose: revenue is <code>Quantity × UnitPrice × (1 − Discount)</code>, and the price lives in the product table.</p>` },
      { h: "Tasks", body: `
        <ol>
          <li><b>Load and set types.</b> Load all four files. Make sure OrderDate and Date are the Date type, Quantity is a whole number, and Discount and UnitPrice are decimals.</li>
          <li><b>Model.</b> Create one-to-many relationships from the dimensions to the fact table: products[ProductID] to orders[ProductID], customers[CustomerID] to orders[CustomerID], and dim_date[Date] to orders[OrderDate]. Keep cross-filter direction Single. Mark dim_date as a date table.</li>
          <li><b>Write three measures</b> (try before you look at the hints below):
            <ul>
              <li><b>Total Sales</b>: revenue summed over every order row.</li>
              <li><b>Sales LY</b>: Total Sales for the same period in the previous year.</li>
              <li><b>YoY %</b>: the percentage change from Sales LY to Total Sales, avoiding division errors.</li>
            </ul></li>
          <li><b>Build one report page</b> with a card for Total Sales, a line chart of Total Sales by month, a bar chart by Category, and a slicer for Year. Add alt text to each visual.</li>
        </ol>
        <details class="faq"><summary>Show measure hints</summary>
          ${pre(`Total Sales =
SUMX (
    orders,
    orders[Quantity] * RELATED ( products[UnitPrice] ) * ( 1 - orders[Discount] )
)

Sales LY =
CALCULATE ( [Total Sales], SAMEPERIODLASTYEAR ( dim_date[Date] ) )

YoY % =
DIVIDE ( [Total Sales] - [Sales LY], [Sales LY] )`)}
          <p><code>SUMX</code> is an iterator, so it can multiply across tables row by row. <code>DIVIDE</code> returns BLANK instead of an error when the denominator is zero or blank.</p>
        </details>` },
      { h: "Expected values", body: `
        <details class="faq"><summary>Show the answer key</summary>
          ${table(["Check", "Expected"], [
            ["Total Sales, no filter", money(p3.total_sales_all)],
            ["Total Sales, Year = 2024", money(p3.sales_2024)],
            ["Total Sales, Year = 2025", money(p3.sales_2025)],
            ["Sales LY, Year = 2025", money(p3.sales_2024)],
            ["YoY %, Year = 2025", p3.yoy_percent_2025 + "%"],
            ["Sales LY and YoY %, Year = 2024", "Blank (there is no 2023 data)"],
            ["Total Sales, Year = 2025 and Category = Electronics", money(p3.sales_electronics_2025)],
          ])}
          <p><b>Total Sales by quarter, 2025</b></p>
          ${table(["Quarter", "Total Sales"], Object.entries(p3.sales_by_quarter_2025).map(([k, v]) => [k, money(v)]))}
          ${VERIFY("These values were computed by script with exact decimal arithmetic from the files you download; the DAX was not run in Power BI.")}
        </details>` },
      { h: "Stretch ideas", body: `
        <ul>
          <li>Add a Sales YTD measure with <code>TOTALYTD</code>.</li>
          <li>Add a Customer Segment slicer and check how the card changes.</li>
          <li>Create a drillthrough page for one Category.</li>
          <li>Explain in two sentences why dim_date must have no gaps.</li>
        </ul>` },
    ],
  };

  return [proj1, proj2, proj3];
};
